    Bug 1835697 - Accept authEnveloped-data smime-type in S/MIME MIME dispatch. r=kaie

    Allow CMS message with AuthEnvelopedData to be decrypted properly in Thunderbird using the code added in D288495.

    Differential Revision: https://phabricator.services.mozilla.com/D295346

diff --git a/mailnews/mime/src/mimecms.cpp b/mailnews/mime/src/mimecms.cpp
index 9ed788eba53..849a55d1326 100644
--- a/mailnews/mime/src/mimecms.cpp
+++ b/mailnews/mime/src/mimecms.cpp
@@ -534,7 +534,8 @@ static MimeClosure MimeCMS_init(MimeObject* obj,
       // We cannot rely on having smime-type, the parameter is optional,
       // but if we have it, do a sanity check.
       if (thisST && PL_strcasecmp(thisST, "enveloped-data") &&
-          PL_strcasecmp(thisST, "signed-data")) {
+          PL_strcasecmp(thisST, "signed-data") &&
+          PL_strcasecmp(thisST, "authEnveloped-data")) {
         NS_WARNING(
             "mimei.cpp shouldn't have routed this smime-type to this CMS "
             "decoder");
diff --git a/mailnews/mime/src/mimei.cpp b/mailnews/mime/src/mimei.cpp
index ff3378c9f3f..a652d7b53ec 100644
--- a/mailnews/mime/src/mimei.cpp
+++ b/mailnews/mime/src/mimei.cpp
@@ -723,7 +723,8 @@ MimeObjectClass* mime_find_class(const char* content_type, MimeHeaders* hdrs,
               if (parentIsEnveloped) {
                 thisPartIsAllowed = true;
               }
-            } else if (!PL_strcasecmp(thisST, "enveloped-data")) {
+            } else if (!PL_strcasecmp(thisST, "enveloped-data") ||
+                       !PL_strcasecmp(thisST, "authEnveloped-data")) {
               // Allowed only if parent is signed
               if (parentIsSigned) {
                 thisPartIsAllowed = true;
